import std.io

pub type AppError = Failed(String)

interface Describe {
    fn describe(self) -> String
}

record Cell { n: Int64 }
newtype Celsius(Int64)

impl Describe for Cell {
    fn describe(self) -> String { "cell" }
}
impl Describe for Celsius {
    fn describe(self) -> String { "c" }
}

pub fn main() effect io -> Result<(), AppError> {
    let cold = Dyn<Describe>(Celsius(5))
    let held = Dyn<Describe>(Cell { n: 7 })
    var acc: Int64 = 0
    var i: Int64 = 0
    while i < 120000 {
        let c = Cell { n: i }
        acc = acc + c.n
        i = i + 1
    }
    io.println("${acc}")
    return Ok(())
}
